    constructor(C _c) { c = _c; }

    function run(uint lockTime, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        (uint balBefore, ) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

