contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint amount) public payable {
        require(amount > 0 && amount <= 1000000000000000000, "amount out of range");
        require(address(this).balance >= amount, "insufficient balance");

        // Deploy the log file contract and set it as the log destination before any Put
        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        // Record the caller's balance before the deposit
        (, uint beforeBalance) = c.Acc(address(this));

        // Make the deposit
        c.Put{value: amount}(lockTime);

        // The caller's balance must have increased by exactly the deposited amount
        (, uint afterBalance) = c.Acc(address(this));
        assert(afterBalance == beforeBalance + amount);
    }

    receive() external payable {}
}

