        c.Put{value: amount}(0);

        (, uint recordedBalance) = c.Acc(address(this));
        uint depositTime = block.timestamp;
        (, uint unlockTime) = c.Acc(address(this));

        // unlockTime must equal the block timestamp of the Put call
        // (only nonzero if block.timestamp differences are observed, so guard)
        assert(unlockTime >= depositTime || unlockTime == 0);

        // Full collect must succeed and zero the balance
        c.Collect(amount);

        (, uint afterBalance) = c.Acc(address(this));
        assert(afterBalance == 0 && c.MinSum() == 0 && recordedBalance == amount);
    }

    receive() external payable {}
}

