contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint lockTime, uint amount, uint collectAm) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        bool putReverted;
        try c.Put{value: amount}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));

        // If the Put succeeded, the sender's balance must have increased by the
        // supplied amount (balance is never mutated by any other successful path
        // before the holder has an unlock time). If Put reverted, no persisted
        // state change is observable through Acc.
        assert(
            (putReverted && beforeUnlockTime == afterUnlockTime && beforeBalance == afterBalance)
            || (!putReverted && afterUnlockTime >= lockTime && afterBalance == beforeBalance + amount && afterBalance >= amount)
        );
    }

    receive() external payable {}
}

